package com.tiny.browser;import android.os.Bundle;import android.webkit.*;import android.widget.*;public class MainActivity extends android.app.Activity{protected void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);EditText u=new EditText(this);WebView w=new WebView(this);w.setWebViewClient(new WebViewClient());l.addView(u);l.addView(w,new LinearLayout.LayoutParams(-1,-1,1));setContentView(l);u.setOnEditorActionListener((v,a,e)->{String s=u.getText().toString();w.loadUrl(s.startsWith("http")?s:"https://"+s);return false;});}}
